def remove_Occ(string, char):
    if not string:
        return ""

    n = len(string)
    first = -1
    last = -1

    for i in range(n):
        if string[i] == char:
            if first == -1:
                first = i
            last = i

    if first == -1:
        return string

    if first == last:
        return string[:first] + string[first+1:]

    # Remove last occurrence first to ensure first index is valid
    string = string[:last] + string[last+1:]
    string = string[:first] + string[first+1:]

    return string

