def count_Substrings(s):
    count = 0
    prefix_sum = 0
    prefix_count = {0: 1}

    for ch in s:
        digit = int(ch)
        prefix_sum += digit - 1

        if prefix_sum in prefix_count:
            count += prefix_count[prefix_sum]

        prefix_count[prefix_sum] = prefix_count.get(prefix_sum, 0) + 1

    return count

