def eulerian_num(n, m):
    if n == 0 and m == 0:
        return 1
    if n < 0 or m < 0 or m > n:
        return 0

    # dp[i][j] stores A(i, j)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            if j == 0:
                dp[i][j] = 1
            elif j == i - 1:
                dp[i][j] = 1
            else:
                dp[i][j] = (i - j) * dp[i - 1][j - 1] + (j + 1) * dp[i - 1][j]

    return dp[n][m]

