def common_in_nested_lists(nested_list):
    if not nested_list:
        return []

    # Convert each inner list to a set for O(1) lookups
    sets = [set(inner) for inner in nested_list]

    # Compute intersection of all sets
    common = sets[0]
    for s in sets[1:]:
        common &= s

    # Convert back to list
    return list(common)

