    return total

def find_length(s: str) -> int:
    if not s:
        return 0

    max_ending_here = 0
    max_so_far = -float('inf')

    for char in s:
        if char == '0':
            max_ending_here += 1
        else:
            max_ending_here -= 1

        max_so_far = max(max_so_far, max_ending_here)

        # Reset if max_ending_here becomes negative
        if max_ending_here < 0:
            max_ending_here = 0

    return max_so_far

