solution:
def magic_square_test(matrix):
    if not matrix or len(matrix) == 0:
        return False

    n = len(matrix)
    if n == 0:
        return False

    # Validate square structure
    for row in matrix:
        if len(row) != n:
            return False

    # Compute target sum from first row
    target_sum = sum(row[0] for row in matrix)

    # Check rows
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != target_sum:
        return False

    # Check secondary diagonal
    secondary_diag_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if secondary_diag_sum != target_sum:
        return False

    return True
